<?php
if(!defined('ABSPATH')){exit;}
function awsw_case_kinds(){return ['volunteer'=>['Volunteer application','رضاکار درخواست'],'assistance'=>['Assistance request','معاونت کی درخواست'],'partnership'=>['Partnership enquiry','شراکت کی درخواست'],'contact'=>['Contact enquiry','رابطہ درخواست']];}
function awsw_case_cap($kind){return $kind==='assistance'?'awsw_manage_assistance':'awsw_manage_enquiries';}
function awsw_case_statuses(){return ['new'=>['New','نئی'],'reviewing'=>['Reviewing','زیرِ جائزہ'],'accepted'=>['Accepted','منظور'],'declined'=>['Declined','نامنظور']];}
function awsw_case_submit(){
    $kind=sanitize_key(awsw_request('kind'));if(!isset(awsw_case_kinds()[$kind])){awsw_fail('Invalid request type.','درخواست کی قسم درست نہیں۔');}awsw_form_guard($kind);
    $token=awsw_request('submission');if(!preg_match('/^[a-f0-9]{48}$/D',$token)||!hash_equals(hash_hmac('sha256',$token,wp_salt('nonce')),awsw_request('signature'))){awsw_fail('Reload the form. The request signature is invalid.','فارم دوبارہ کھولیں۔ درخواست کی شناخت درست نہیں۔',403);}
    global $wpdb;$table=$wpdb->prefix.'awsw_enquiries';$hash=hash('sha256',$token);$confirmation=add_query_arg('kind',$kind,awsw_url('submission-confirmation/'));
    if($wpdb->get_var($wpdb->prepare("SELECT id FROM $table WHERE submission_hash=%s",$hash))){awsw_redirect($confirmation);}
    $data=[];foreach(['name','email','phone','city','interests','skills','availability','preference','message','organization','contact_method','category'] as $key){$value=awsw_request($key);if(mb_strlen($value)>3000){awsw_fail('A field is too long. Please shorten it.','متن بہت طویل ہے۔ اسے مختصر کریں۔');}$data[$key]=$key==='email'?sanitize_email($value):sanitize_textarea_field($value);}
    $required=['name','message'];if($kind==='assistance'){$required=array_merge($required,['contact_method','city','interests']);}else{$required[]='email';if(!is_email($data['email'])){awsw_fail('Enter a valid email address.','درست ای میل درج کریں۔');}}
    if($kind==='volunteer'){$required=array_merge($required,['phone','city','interests','skills','availability','preference']);}if($kind==='partnership'){$required=array_merge($required,['organization','interests']);}
    foreach($required as $key){if(!$data[$key]){awsw_fail('Complete all required fields before submitting. Your entered values are kept in the form.','بھیجنے سے پہلے ضروری خانے پُر کریں۔ درج شدہ معلومات فارم میں موجود رہیں گی۔');}}
    if(mb_strlen($data['name'])>190||strlen($data['email'])>190||mb_strlen($data['phone'])>40||awsw_request('consent')!=='1'){awsw_fail('Check your name, contact details and consent.','نام، رابطہ معلومات اور رضامندی چیک کریں۔');}
    if(in_array($kind,['volunteer','assistance'],true)&&!isset(awsw_programs()[$data['interests']])){awsw_fail('Choose one of the listed programs.','دیے گئے شعبوں میں سے منتخب کریں۔');}
    if($kind==='volunteer'&&!in_array($data['preference'],['onsite','remote','either'],true)){awsw_fail('Choose an availability preference.','دستیابی کا طریقہ منتخب کریں۔');}
    if(!awsw_rate_limit('case_'.$kind)){awsw_fail('Please wait 20 seconds before another request.','دوبارہ درخواست سے پہلے ۲۰ سیکنڈ انتظار کریں۔',429);}
    if(!$wpdb->insert($table,['kind'=>$kind,'payload'=>wp_json_encode($data),'submission_hash'=>$hash,'status'=>'new','created_at'=>current_time('mysql',true)])){
        if($wpdb->get_var($wpdb->prepare("SELECT id FROM $table WHERE submission_hash=%s",$hash))){awsw_redirect($confirmation);}awsw_fail('We could not save your request. Please retry; your form has not been cleared.','درخواست محفوظ نہیں ہوئی۔ دوبارہ کوشش کریں؛ فارم کی معلومات موجود ہیں۔',503);
    }
    $id=$wpdb->insert_id;$to=sanitize_email(awsw_setting('notification_email'))?:get_option('admin_email');$sent=wp_mail($to,'AWS Welfare: new '.$kind.' request','A private request is available to authorized staff: '.admin_url('admin.php?page='.($kind==='assistance'?'awsw-assistance':'awsw-enquiries').'&kind='.$kind));$wpdb->update($table,['email_state'=>$sent?'accepted':'failed'],['id'=>$id]);awsw_redirect($confirmation);
}
function awsw_case_form($kind){
    if(!isset(awsw_case_kinds()[$kind])){return '';}$token=bin2hex(random_bytes(24));ob_start();
    echo '<form class="awsw-form awsw-enquiry" method="post" action="'.esc_url(add_query_arg('lang',awsw_lang(),admin_url('admin-post.php'))).'">';awsw_form_hidden($kind);
    echo '<input name="kind" type="hidden" value="'.esc_attr($kind).'"><input name="submission" type="hidden" value="'.esc_attr($token).'"><input name="signature" type="hidden" value="'.esc_attr(hash_hmac('sha256',$token,wp_salt('nonce'))).'">';
    echo '<div class="awsw-error-summary" role="alert" tabindex="-1" hidden></div><div class="awsw-form-grid">';
    awsw_input('name',awsw_t('Full name','مکمل نام'),'text',true,'name');
    if($kind==='assistance'){awsw_input('contact_method',awsw_t('How can we contact you? Phone or email','رابطے کے لیے فون یا ای میل'));}else{awsw_input('email',awsw_t('Email address','ای میل'),'email',true,'email');awsw_input('phone',awsw_t('Phone','فون'),'tel',$kind==='volunteer','tel');}
    if(in_array($kind,['volunteer','assistance'],true)){awsw_input('city',awsw_t('City or general area','شہر یا عمومی علاقہ'));}
    if($kind==='partnership'){awsw_input('organization',awsw_t('Organization name','ادارے کا نام'));}
    if($kind!=='contact'){
        echo '<label for="awsw-interests">'.esc_html(awsw_t($kind==='partnership'?'Partnership interest':'Preferred program',$kind==='partnership'?'شراکت میں دلچسپی':'متعلقہ شعبہ')).'</label><select name="interests" id="awsw-interests" required>';
        $options=$kind==='partnership'?['sponsorship'=>['Campaign sponsorship','مہم کی سرپرستی'],'in-kind'=>['In-kind support','اشیاء کی صورت میں مدد'],'employee'=>['Employee volunteering','ملازمین کی رضاکارانہ خدمت']]:array_map(fn($p)=>[$p[0],$p[1]],awsw_programs());
        foreach($options as $value=>$label){echo '<option value="'.esc_attr($value).'">'.esc_html(awsw_t(...$label)).'</option>';}echo '</select>';
    }else{echo '<label for="awsw-category">'.esc_html(awsw_t('Inquiry category','رابطے کی نوعیت')).'</label><select id="awsw-category" name="category">';foreach(['general'=>['General question','عمومی سوال'],'donation'=>['Donation query','عطیات سے متعلق'],'reports'=>['Reports & transparency','رپورٹس اور شفافیت']] as $v=>$l){echo '<option value="'.esc_attr($v).'">'.esc_html(awsw_t(...$l)).'</option>';}echo '</select>';}
    if($kind==='volunteer'){awsw_input('skills',awsw_t('Skills you would like to share','وہ مہارتیں جن سے آپ مدد کریں گے'));awsw_input('availability',awsw_t('Availability: days and hours','دستیابی: دن اور اوقات'));echo '<label for="awsw-preference">'.esc_html(awsw_t('Preferred way to volunteer','خدمت کا پسندیدہ طریقہ')).'</label><select id="awsw-preference" name="preference" required>';foreach(['onsite'=>['On-site','موقع پر'],'remote'=>['Remote','آن لائن'],'either'=>['Either, where suitable','ضرورت کے مطابق دونوں']] as $v=>$l){echo '<option value="'.esc_attr($v).'">'.esc_html(awsw_t(...$l)).'</option>';}echo '</select>';}
    echo '</div><label for="awsw-message">'.esc_html(awsw_t($kind==='volunteer'?'Why would you like to help?':'Brief description',$kind==='volunteer'?'آپ خدمت کیوں کرنا چاہتے ہیں؟':'مختصر تفصیل')).'</label><textarea id="awsw-message" name="message" rows="5" maxlength="3000" required></textarea>';
    if($kind==='assistance'){echo '<p class="awsw-notice">'.esc_html(awsw_t('Please do not include CNIC numbers, medical records, bank passwords or private documents. Submission does not guarantee assistance.','شناختی کارڈ نمبر، طبی ریکارڈ، بینک پاس ورڈ یا نجی دستاویزات شامل نہ کریں۔ درخواست سے مدد کی ضمانت نہیں ہوتی۔')).'</p>';}
    awsw_consent();echo '<button class="awsw-button" type="submit">'.esc_html(awsw_t('Submit for review','جائزے کے لیے بھیجیں')).' '.awsw_icon('arrow').'</button><p class="awsw-live" role="status" aria-live="polite"></p></form>';return ob_get_clean();
}
add_action('init',function(){remove_shortcode('awsw_enquiry');add_shortcode('awsw_enquiry',function($attrs){$a=shortcode_atts(['type'=>'contact'],$attrs);return awsw_case_form(sanitize_key($a['type']));});});
add_shortcode('awsw_submission_confirmation',function(){return '<div class="awsw-confirmation"><span aria-hidden="true">✓</span><h2>'.esc_html(awsw_t('Thank you. Your request has been saved.','شکریہ۔ آپ کی درخواست محفوظ ہو گئی ہے۔')).'</h2><p>'.esc_html(awsw_t('Authorized staff will review your request. This is not a promise of acceptance or assistance. Email notification is separate; a mail failure does not remove your saved application.','مجاز عملہ درخواست کا جائزہ لے گا۔ یہ منظوری یا معاونت کا وعدہ نہیں۔ ای میل الگ عمل ہے؛ اس کی ناکامی سے محفوظ درخواست حذف نہیں ہوتی۔')).'</p>'.awsw_button(awsw_t('Back to Get Involved','شمولیت کے صفحے پر جائیں'),awsw_url('get-involved/')).'</div>';});
function awsw_cases_admin(){
    $kind=sanitize_key($_GET['kind']??'contact');if(!isset(awsw_case_kinds()[$kind])){$kind='contact';}awsw_admin_guard(awsw_case_cap($kind));global $wpdb;awsw_admin_start('AWS Welfare · '.awsw_case_kinds()[$kind][0]);
    echo '<nav class="nav-tab-wrapper">';foreach(awsw_case_kinds() as $k=>$label){if(current_user_can(awsw_case_cap($k))){echo '<a class="nav-tab '.($k===$kind?'nav-tab-active':'').'" href="'.esc_url(admin_url('admin.php?page='.($k==='assistance'?'awsw-assistance':'awsw-enquiries').'&kind='.$k)).'">'.esc_html($label[0]).'</a>';}}echo '</nav>';
    $status=sanitize_key($_GET['status']??'');$where='kind=%s';$args=[$kind];if(isset(awsw_case_statuses()[$status])){$where.=' AND status=%s';$args[]=$status;}
    echo '<form><input name="page" type="hidden" value="awsw-enquiries"><input name="kind" type="hidden" value="'.esc_attr($kind).'"><label>Application status <select name="status"><option value="">All</option>';foreach(awsw_case_statuses() as $s=>$l){echo '<option value="'.esc_attr($s).'" '.selected($status,$s,false).'>'.esc_html($l[0]).'</option>';}echo '</select></label> <button class="button">Filter</button></form>';
    $page=max(1,absint($_GET['paged']??1));$args[]=($page-1)*25;$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}awsw_enquiries WHERE $where ORDER BY id DESC LIMIT 25 OFFSET %d",$args));
    foreach($rows as $r){echo '<details class="awsw-admin-case"><summary><strong>#'.(int)$r->id.'</strong> · <span class="awsw-admin-badge">'.esc_html($r->status).'</span> · '.esc_html(awsw_time($r->created_at)).' · email '.esc_html($r->email_state).'</summary><dl>';foreach((array)json_decode($r->payload,true) as $k=>$v){if($v!==''){echo '<dt><strong>'.esc_html($k).'</strong></dt><dd>'.esc_html($v).'</dd>';}}echo '</dl><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="awsw_case_status"><input name="id" type="hidden" value="'.(int)$r->id.'">';wp_nonce_field('awsw_case_'.$r->id);echo '<label>Status <select name="status">';foreach(awsw_case_statuses() as $s=>$label){echo '<option value="'.esc_attr($s).'" '.selected($r->status,$s,false).'>'.esc_html($label[0]).'</option>';}echo '</select></label><p><label>Staff note (no unnecessary sensitive information)<br><textarea required name="note" rows="3" maxlength="2000"></textarea></label></p><button class="button button-primary">Save review</button></form><h3>Review history</h3><ul>';foreach($wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}awsw_case_events WHERE case_id=%d ORDER BY id",$r->id)) as $e){echo '<li>'.esc_html(awsw_time($e->created_at).' · staff #'.$e->actor_id.' · '.$e->old_status.' → '.$e->new_status.' · '.$e->note).'</li>';}echo '</ul><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="awsw_delete_enquiry"><input type="hidden" name="id" value="'.(int)$r->id.'">';wp_nonce_field('awsw_delete_'.$r->id);echo '<label><input required type="checkbox" name="confirm" value="1"> Permanently delete this application under the approved retention policy</label> <button class="button">Delete application</button></form></details>';}
    if(!$rows){echo '<p>No matching applications yet.</p>';}if($page>1){echo '<a class="button" href="'.esc_url(add_query_arg('paged',$page-1)).'">Previous</a> ';}if(count($rows)===25){echo '<a class="button" href="'.esc_url(add_query_arg('paged',$page+1)).'">Next</a>';}echo '</div>';
}
add_action('admin_post_awsw_case_status',function(){global $wpdb;$id=absint(awsw_request('id'));$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}awsw_enquiries WHERE id=%d",$id));if(!$r){wp_die('Not found.','',['response'=>404]);}awsw_admin_guard(awsw_case_cap($r->kind));check_admin_referer('awsw_case_'.$id);$status=sanitize_key(awsw_request('status'));$note=sanitize_textarea_field(awsw_request('note'));if(!isset(awsw_case_statuses()[$status])||!$note||mb_strlen($note)>2000){wp_die('Choose a valid status and brief review note.');}
    $wpdb->query('START TRANSACTION');$locked=$wpdb->get_row($wpdb->prepare("SELECT status FROM {$wpdb->prefix}awsw_enquiries WHERE id=%d FOR UPDATE",$id));if(!$locked){$wpdb->query('ROLLBACK');wp_die('Request no longer exists.','',['response'=>404]);}$ok=$wpdb->update($wpdb->prefix.'awsw_enquiries',['status'=>$status],['id'=>$id]);$logged=$wpdb->insert($wpdb->prefix.'awsw_case_events',['case_id'=>$id,'actor_id'=>get_current_user_id(),'old_status'=>$locked->status,'new_status'=>$status,'note'=>$note,'created_at'=>current_time('mysql',true)]);if($ok===false||!$logged){$wpdb->query('ROLLBACK');wp_die('Could not save review. Retry safely.');}$wpdb->query('COMMIT');wp_safe_redirect(admin_url('admin.php?page='.($r->kind==='assistance'?'awsw-assistance':'awsw-enquiries').'&kind='.$r->kind.'&awsw_saved=1'));exit;
});
add_action('admin_menu',function(){add_menu_page('Applications & enquiries','Applications','awsw_manage_enquiries','awsw-enquiries','awsw_admin_enquiries','dashicons-clipboard',27);add_menu_page('Assistance requests','Assistance requests','awsw_manage_assistance','awsw-assistance',function(){$_GET['kind']='assistance';awsw_cases_admin();});});
add_action('admin_enqueue_scripts',function(){if(!isset($_GET['page'])||!str_starts_with(sanitize_key($_GET['page']),'awsw')){return;}wp_enqueue_style('awsw-admin',AWSW_URL.'assets/admin.css',[],AWSW_VERSION);});
add_action('admin_init',function(){
    $page=sanitize_key($_GET['page']??'');
    if($page==='awsw-assistance'){awsw_admin_guard('awsw_manage_assistance');}
    elseif($page==='awsw-enquiries'){$kind=sanitize_key($_GET['kind']??'contact');awsw_admin_guard(awsw_case_cap($kind));}
});
